<article class="workout-content event-content" data-event-id="<?php echo esc_attr($detail['id']); ?>"><h3><?php echo esc_html($detail['title']); ?></h3>
<?php if($detail['manage']): ?><div class="plan-actions detail-plan-actions"><a class="control" data-event-action href="<?php echo esc_url($returnUrl.'&edit_event='.$detail['id']); ?>">Edit event</a><a class="control" data-event-action href="<?php echo esc_url($returnUrl.'&event_result='.$detail['id']); ?>">Record race result</a></div><?php endif; ?>
<dl class="workout-metrics"><?php foreach($detail['summary']as$label=>$value): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php endforeach; ?></dl>
<?php if($detail['manage']): ?><section><h3>Race result</h3><?php if($detail['result']['time']===''&&$detail['result']['placement']===null): ?><p>No race result has been recorded.</p><?php else: ?><dl class="workout-metrics"><div><dt>Race time</dt><dd><?php echo esc_html($detail['result']['time']!==''?$detail['result']['time']:'—'); ?></dd></div><div><dt>Placement</dt><dd><?php echo esc_html($detail['result']['placement']??'—'); ?></dd></div></dl><?php endif; ?></section><section><h3>Event notes</h3><?php if($detail['notes']!==''): ?><p class="instructions"><?php echo esc_html($detail['notes']); ?></p><?php else: ?><p>No event notes have been added.</p><?php endif; ?></section><?php endif; ?></article>
